CREATE OR REPLACE VIEW `get_imagesproducts` AS select `p`.`company_id` AS `company_id`,`pi`.`product_id` AS `product_id`,count(`pi`.`img_id`) AS `qty_images`,group_concat(`i`.`path` order by `pi`.`img_order` ASC separator ',') AS `group_images` from ((`product_images` `pi` join `products` `p` on(`p`.`pro_id` = `pi`.`product_id`)) left join `images` `i` on(`i`.`uuid` = `pi`.`image_id`)) where `pi`.`product_id` is not null and `pi`.`deleted_at` is null group by `pi`.`product_id`,`p`.`company_id`;
